style.css:
@-moz-document domain("dcard.tw") {
/* Dcard 用 :root 上的 semantic token 驅動整個配色，component 是每次 deploy 會變的
     hash atomic class（d_a5_1vf95…）。所以只覆寫 token，不碰 class，改版也不會壞。 */
  :root {
    color-scheme: dark;

    /* ---- Backgrounds ---- */
    --color-bg-base-1: #0f1113 !important;              /* app/page base */
    --color-bg-base-2: #1a1c1f !important;              /* cards / 文章本體 */
    --color-bg-base-3: #212429 !important;              /* elevated surface */
    --color-bg-container: rgba(255, 255, 255, 0.06) !important;
    --color-bg-light: #1a1c1f !important;
    --color-bg-btn-disabled: #2a2d31 !important;
    --color-bg-grey-btn-hover: rgba(255, 255, 255, 0.06) !important;
    --color-bg-moderator-empty: rgba(255, 255, 255, 0.1) !important;
    --color-shimmer-bg: #1c1e21 !important;
    --color-shimmer-fg: #26292e !important;
    --color-dcard-hint: #0e2331 !important;             /* pale-blue hint -> dark blue */
    --color-bg-sticker-preview: rgba(26, 28, 31, 0.8) !important;

    /* ---- Text（黑字翻成亮字）---- */
    --color-text-primary: rgba(255, 255, 255, 0.87) !important;
    --color-text-secondary: rgba(255, 255, 255, 0.55) !important;
    --color-text-hint: rgba(255, 255, 255, 0.4) !important;
    --color-text-disabled: rgba(255, 255, 255, 0.3) !important;
    --color-text-dark-primary: rgba(255, 255, 255, 0.87) !important;
    --color-text-dark-secondary: rgba(255, 255, 255, 0.55) !important;
    --color-icon-button: rgba(255, 255, 255, 0.72) !important;
    --color-text-login-btn: rgba(255, 255, 255, 0.87) !important;
    --color-text-default-hovered: rgba(255, 255, 255, 0.4) !important;

    /* ---- Borders / separators ---- */
    --color-border: #34383d !important;
    --color-border-disabled: #2a2d31 !important;
    --color-separator: rgba(255, 255, 255, 0.12) !important;
  }

  /* ---- Structural safety net（非 token 的表面才需要）---- */

  /* 保底：萬一某層在 token 外硬寫白底 */
  html,
  body {
    background-color: var(--color-bg-base-1);
  }

  /* /forum/all 等頁面把「白色文字」token（--color-text-light-primary #fff）
     直接拿來當背景（看板分類清單就是），token 本身不能改（側欄白字還要用）。
     d_2e_ 是 Dcard atomic 的 background-color atom，srmx5f 是該 value 的 hash，
     只翻背景那顆、不動同 hash 的文字色 atom（d_2l_）。
     ponytail: 這是唯一綁 hash 的規則；Dcard 若重排 atom 表可能失效，屆時重掃 background:#fff 的 class 換掉即可。 */
  .d_2e_srmx5f {
    background-color: var(--color-bg-base-2) !important;
  }

  /* 深色捲軸 */
  ::-webkit-scrollbar {
    width: 10px;
    height: 10px;
    background: transparent;
  }
  ::-webkit-scrollbar-track {
    background: transparent;
  }
  ::-webkit-scrollbar-thumb {
    background: rgba(255, 255, 255, 0.2);
    border-radius: 5px;
  }
  ::-webkit-scrollbar-thumb:hover {
    background: rgba(255, 255, 255, 0.3);
  }
}
